# Every input and output of this project, on the box's own channels so it
# runs with nothing wired. To use a remote I/O module, declare it and change
# the device on each line, for example:
#   device rio modbus-tcp 192.168.1.50:502 unit=1 timeout_ms=300 poll_ms=20
#   in  start_pb bool rio di:0
# The plant model presses start by itself, so if this box's own channels are
# wired to anything, these lines drive it: check them before you deploy.
in  start_pb             bool box di:0
in  stop_pb              bool box di:1
in  ack_pb               bool box di:2
in  inlet_open_in        bool box di:3
in  inlet_closed_in      bool box di:4
in  outlet_open_in       bool box di:5
in  outlet_closed_in     bool box di:6
in  agitator_fb_in       bool box di:7
in  agitator_overload_in bool box di:8
in  overtemp_in          bool box di:9
in  sim_inlet_stuck      bool box di:10
out inlet_valve  bool box do:0 safe=false
out outlet_valve bool box do:1 safe=false
out agitator     bool box do:2 safe=false
out heater       bool box do:3 safe=false
out lamp_green   bool box do:4 safe=false
out lamp_red     bool box do:5 safe=false
out step    int  screen step safe=0
out batches int  screen batches safe=0
out level_m real screen level_m unit=m
out temp_c  real screen temp_c unit=degC
